try{New-Item -ItemType Directory -Path $stage|Out-Null;$customers=@([ordered]@{id='CUS-SYN-A';projects=@('PRJ-SYN-A1','PRJ-SYN-A2')},[ordered]@{id='CUS-SYN-B';projects=@('PRJ-SYN-B1')});$catalogCustomers=@();foreach($c in $customers){$projects=@();foreach($p in $c.projects){$suffix=($p-replace'^PRJ-SYN-','');$snapshot=New-Snapshot $c.id $p $suffix;$releaseId="SRL-$suffix-001";$releaseRel="customers/$($c.id)/projects/$p/snapshots/releases/$($snapshot.snapshot_id)/release.json";$releaseDir=Join-Path $stage ((Split-Path $releaseRel -Parent)-replace'/',[IO.Path]::DirectorySeparatorChar);New-Item -ItemType Directory -Path $releaseDir -Force|Out-Null;$snapshotPath=Join-Path $releaseDir 'snapshot.json';Write-PortableJson $snapshotPath $snapshot;$digest=Get-PortableSha $snapshotPath;$content=[Convert]::ToBase64String([IO.File]::ReadAllBytes($snapshotPath));$release=[ordered]@{schema_version=1;product_id='spectra';release_id=$releaseId;snapshot_id=$snapshot.snapshot_id;customer_id=$c.id;project_id=$p;state='approved';immutable=$true;snapshot_path='snapshot.json';snapshot_sha256=$digest;transports=[ordered]@{contract_id='spectra-portable-project-snapshot-v1';media_type='application/vnd.spectra.project-snapshot+json';filesystem=[ordered]@{location='snapshot.json';payload_sha256=$digest};http=[ordered]@{location="/v1/customers/$($c.id)/projects/$p/snapshots/$($snapshot.snapshot_id)";payload_sha256=$digest;content_base64=$content}}};Write-PortableJson (Join-Path $releaseDir 'release.json') $release;$currentPath=Join-Path $stage "customers\$($c.id)\projects\$p\snapshots\current.json";Write-PortableJson $currentPath ([ordered]@{release_id=$releaseId;release_manifest_path=$releaseRel;snapshot_sha256=$digest});$projects+=[ordered]@{project_id=$p;release_manifest_path=$releaseRel;release_id=$releaseId;snapshot_sha256=$digest}};$catalogCustomers+=[ordered]@{customer_id=$c.id;visibility='isolated';projects=$projects}};$catalog=[ordered]@{schema_version=1;product_id='spectra';catalog_id